"use client";
import {useEffect,useMemo,useState} from 'react';
import {Map,Scale,Cpu,ChartNoAxesCombined,BookOpen,MessageSquare,ArrowUpRight,ArrowRight,Check,ChevronRight,Download,LogIn,RefreshCw,Search,Settings2,ShieldCheck,X,Plus,Info,AlertTriangle,Menu,PlugZap,Save,ExternalLink} from 'lucide-react';
import EuropeMap from './components/europe-map';
import DecisionSummary from './components/decision-summary';
import seed from '@/data/seed.json';
